-- Odoo-inspired CRM, enterprise and product master-data alignment.
alter table public.crm_accounts add column if not exists company_type text not null default 'company', add column if not exists is_archived boolean not null default false, add column if not exists archived_at timestamptz, add column if not exists archived_reason text;
alter table public.crm_contacts add column if not exists is_archived boolean not null default false, add column if not exists archived_at timestamptz, add column if not exists archived_reason text;
alter table public.crm_opportunities add column if not exists is_archived boolean not null default false, add column if not exists archived_at timestamptz, add column if not exists archived_reason text, add column if not exists forecast_probability numeric(5,2), add column if not exists team_id uuid;
alter table public.enterprise_profiles add column if not exists parent_enterprise_id uuid, add column if not exists branch_code text, add column if not exists is_branch boolean not null default false, add column if not exists is_archived boolean not null default false, add column if not exists archived_at timestamptz, add column if not exists archived_reason text;
alter table public.enterprise_bank_accounts add column if not exists is_archived boolean not null default false, add column if not exists archived_at timestamptz, add column if not exists archived_reason text;
do $$ begin if not exists(select 1 from pg_constraint where conname='crm_accounts_company_type_check') then alter table public.crm_accounts add constraint crm_accounts_company_type_check check(company_type in ('company','person')) not valid; end if; if not exists(select 1 from pg_constraint where conname='enterprise_profiles_parent_enterprise_id_fkey') then alter table public.enterprise_profiles add constraint enterprise_profiles_parent_enterprise_id_fkey foreign key(parent_enterprise_id) references public.enterprise_profiles(id) on delete restrict not valid; end if; end $$;
create table if not exists public.crm_account_addresses(id uuid primary key default gen_random_uuid(),owner_id uuid not null,account_id uuid not null references public.crm_accounts(id) on delete restrict,contact_id uuid references public.crm_contacts(id) on delete set null,address_type text not null default 'other' check(address_type in ('invoice','delivery','other','private')),name text,street text,street2 text,city text,state text,postal_code text,country_code text,phone text,email text,is_default boolean not null default false,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.trade_product_categories(id uuid primary key default gen_random_uuid(),owner_id uuid not null,parent_id uuid references public.trade_product_categories(id) on delete restrict,name text not null,code text,description text,sequence integer not null default 10,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
alter table public.trade_products add column if not exists category_id uuid references public.trade_product_categories(id) on delete restrict,add column if not exists product_type text not null default 'goods',add column if not exists tracking text not null default 'none',add column if not exists is_archived boolean not null default false,add column if not exists archived_at timestamptz,add column if not exists archived_reason text;
create table if not exists public.trade_product_attributes(id uuid primary key default gen_random_uuid(),owner_id uuid not null,name text not null,display_type text not null default 'select' check(display_type in ('select','radio','color','multi')),create_variant text not null default 'always' check(create_variant in ('always','dynamic','never')),sequence integer not null default 10,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists public.trade_product_attribute_values(id uuid primary key default gen_random_uuid(),owner_id uuid not null,attribute_id uuid not null references public.trade_product_attributes(id) on delete restrict,name text not null,sequence integer not null default 10,html_color text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,attribute_id,name));
create table if not exists public.trade_product_template_attribute_lines(id uuid primary key default gen_random_uuid(),owner_id uuid not null,product_id uuid not null references public.trade_products(id) on delete cascade,attribute_id uuid not null references public.trade_product_attributes(id) on delete restrict,value_ids uuid[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,product_id,attribute_id));
create table if not exists public.trade_product_variants(id uuid primary key default gen_random_uuid(),owner_id uuid not null,product_id uuid not null references public.trade_products(id) on delete restrict,sku text,barcode text,name text,attribute_value_ids uuid[] not null default '{}',default_unit_price numeric(20,6),cost_price numeric(20,6),weight numeric(20,6),volume numeric(20,6),is_active boolean not null default true,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.crm_sales_teams(id uuid primary key default gen_random_uuid(),owner_id uuid not null,name text not null,team_leader text,assignment_mode text not null default 'manual' check(assignment_mode in ('manual','round_robin','balanced')),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists public.crm_activities(id uuid primary key default gen_random_uuid(),owner_id uuid not null,activity_type text not null default 'todo',summary text not null,note text,due_at timestamptz,status text not null default 'planned' check(status in ('planned','done','cancelled')),account_id uuid references public.crm_accounts(id) on delete restrict,contact_id uuid references public.crm_contacts(id) on delete set null,opportunity_id uuid references public.crm_opportunities(id) on delete restrict,assigned_to text,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.crm_contacts drop constraint if exists crm_contacts_account_id_fkey; alter table public.crm_contacts add constraint crm_contacts_account_id_fkey foreign key(account_id) references public.crm_accounts(id) on delete restrict not valid;
alter table public.crm_opportunities drop constraint if exists crm_opportunities_account_id_fkey; alter table public.crm_opportunities add constraint crm_opportunities_account_id_fkey foreign key(account_id) references public.crm_accounts(id) on delete restrict not valid;
alter table public.enterprise_bank_accounts drop constraint if exists enterprise_bank_accounts_enterprise_id_fkey; alter table public.enterprise_bank_accounts add constraint enterprise_bank_accounts_enterprise_id_fkey foreign key(enterprise_id) references public.enterprise_profiles(id) on delete restrict not valid;
create index if not exists idx_crm_accounts_owner_company_type on public.crm_accounts(owner_id,company_type,is_archived);
create index if not exists idx_crm_contacts_owner_account on public.crm_contacts(owner_id,account_id,is_archived);
create index if not exists idx_crm_opportunities_owner_account on public.crm_opportunities(owner_id,account_id,status,is_archived);
create index if not exists idx_crm_addresses_owner_account on public.crm_account_addresses(owner_id,account_id,address_type);
create index if not exists idx_enterprise_profiles_owner_parent on public.enterprise_profiles(owner_id,parent_enterprise_id);
create index if not exists idx_trade_products_owner_category on public.trade_products(owner_id,category_id);
create index if not exists idx_trade_product_categories_owner_parent on public.trade_product_categories(owner_id,parent_id);
create index if not exists idx_trade_product_values_owner_attribute on public.trade_product_attribute_values(owner_id,attribute_id);
create index if not exists idx_trade_product_lines_owner_product on public.trade_product_template_attribute_lines(owner_id,product_id);
create index if not exists idx_trade_product_variants_owner_product on public.trade_product_variants(owner_id,product_id);
create index if not exists idx_crm_activities_owner_due on public.crm_activities(owner_id,status,due_at);
alter table public.crm_account_addresses enable row level security; alter table public.trade_product_categories enable row level security; alter table public.trade_product_attributes enable row level security; alter table public.trade_product_attribute_values enable row level security; alter table public.trade_product_template_attribute_lines enable row level security; alter table public.trade_product_variants enable row level security; alter table public.crm_sales_teams enable row level security; alter table public.crm_activities enable row level security;
